update public.activities as activity
set google_place_checked_at = now(),
    google_place_check_status = place_checks.check_status,
    google_business_status = coalesce(place_checks.business_status, activity.google_business_status),
    updated_at = now()
from place_checks
where activity.activity_id = place_checks.activity_id;

-- Google confirmed these stored Place records as permanently closed.
update public.activities
set archive_previous_listing_status = case when public_listing_status in ('draft', 'published') then public_listing_status else archive_previous_listing_status end,
    archive = true,
    public_listing_status = 'archived',
    archive_reason = 'Stale listing: Google Places marks the identity-matched venue permanently closed',
    archived_at = coalesce(archived_at, now()),
    updated_at = now()
where activity_id in ($$01e32f52-07b1-4243-9b62-4bc6abea2f88$$::uuid, $$1841ea9e-d477-426b-96d5-1420049561bf$$::uuid, $$1bece9fc-ddd6-4947-93ac-d68f7a5405e3$$::uuid, $$235c0d31-71a9-405a-801b-085b1330f959$$::uuid, $$26545eb2-60ca-4e02-8b6e-75c20bf9a58a$$::uuid, $$2a708d81-36cf-48ce-b0a0-b19a5105ddbb$$::uuid, $$436afd74-da94-4302-81dd-5af5c1b0039b$$::uuid, $$4944bf03-7a8e-44bf-8416-7028f44f029d$$::uuid, $$6aec6c39-20c5-41ba-add8-c0d0e6cf0ada$$::uuid, $$7116219d-6469-4875-926e-7d51f386235f$$::uuid, $$75b6be66-d253-4c4d-a74b-4bc8a90b7936$$::uuid, $$7e12c540-4092-4925-95cf-ef8189f0f327$$::uuid, $$ba5e4ef7-6c8e-4a15-9eb7-e8e2942e0b9f$$::uuid, $$dbf1a711-e677-4e22-9059-0a1355d63efa$$::uuid, $$dc48124a-f029-43a7-8dd8-a22a0c5ab75c$$::uuid, $$df5f903c-b50d-4629-b780-63507aa8cd1f$$::uuid);
